function validate([edges]) {
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > 99999) return 'edges must hold n - 1 edges for 2 <= n <= 10^5.';
  const n = edges.length + 1;
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (![u, v].every(x => Number.isInteger(x) && x >= 0 && x < n)) return 'Edge endpoints are nodes from 0 to n - 1.';
    if (u === v) return 'An edge must join two different nodes.';
    const ru = find(u), rv = find(v);
    if (ru === rv) return 'The edges must form a tree (no cycles).';
    root[ru] = rv;
  }
  return null;
}

