function timeTaken(edges) {
  const n = edges.length + 1;
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    graph[u].push(v);
    graph[v].push(u);
  }
  const delay = node => (node % 2 === 1 ? 1 : 2);

  const parent = new Array(n).fill(-1);
  const order = [0];
  for (let i = 0; i < order.length; i++) {
    const node = order[i];
    for (const next of graph[node]) {
      if (next !== parent[node]) {
        parent[next] = node;
        order.push(next);
      }
    }
  }

  const down = new Array(n).fill(0);
  const second = new Array(n).fill(0);
  const bestChild = new Array(n).fill(-1);
  for (let i = n - 1; i > 0; i--) {
    const node = order[i];
    const p = parent[node];
    const time = down[node] + delay(node);
    if (time > down[p]) {
      second[p] = down[p];
      down[p] = time;
      bestChild[p] = node;
    } else if (time > second[p]) {
      second[p] = time;
    }
  }

  const up = new Array(n).fill(0);
  const times = new Array(n).fill(0);
  for (const node of order) {
    if (node !== 0) {
      const p = parent[node];
      const sibling = bestChild[p] === node ? second[p] : down[p];
      up[node] = delay(p) + Math.max(up[p], sibling);
    }
    times[node] = Math.max(down[node], up[node]);
  }
  return times;
}

