function timeTaken(edges) {
  // Follow the marking rules literally, one time unit after another, from every starting node.
  const n = edges.length + 1;
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  const result = [];
  for (let start = 0; start < n; start++) {
    const markedAt = new Array(n).fill(-1);
    markedAt[start] = 0;
    let marked = 1, t = 0;
    while (marked < n) {
      t++;
      const now = [];
      for (let v = 0; v < n; v++) {
        if (markedAt[v] >= 0) continue;
        const wait = v % 2 === 1 ? 1 : 2;
        if (adj[v].some(u => markedAt[u] >= 0 && markedAt[u] === t - wait)) now.push(v);
      }
      for (const v of now) markedAt[v] = t;
      marked += now.length;
    }
    result.push(t);
  }
  return result;
}

