function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 11);
  const shape = Math.floor(rand() * 5);
  const pairs = [];
  for (let i = 1; i < n; i++) {
    let p;
    if (shape === 0) p = Math.floor(rand() * i);                          // random tree
    else if (shape === 1) p = i - 1;                                     // path
    else if (shape === 2) p = 0;                                         // star
    else if (shape === 3) p = i % 2 === 1 ? Math.max(0, i - 2) : i - 1;  // caterpillar
    else p = Math.floor((i - 1) / 2);                                    // binary tree
    pairs.push([p, i]);
  }
  // Relabel the nodes, flip edge directions and shuffle the edge order.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [label[i], label[j]] = [label[j], label[i]]; }
  const edges = pairs.map(([a, b]) => (rand() < 0.5 ? [label[a], label[b]] : [label[b], label[a]]));
  for (let i = edges.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  return [edges];
}
